const {ccclass, property} = cc._decorator;

@ccclass
export default class GameOverDialog extends cc.Component {

    @property(cc.Label)
    label: cc.Label = null;

    @property(cc.Button)
    btnYes: cc.Button = null;

    @property(cc.Button)
    btnNo: cc.Button = null;

    onLoad () {
       
    }
    onYes(){
        cc.director.loadScene("Game");
        
    }
    onNo(){
        cc.director.loadScene("Main");
    }
}